/* Main-page data views and evidence. Values come from the supplied report data. */
function modelLabel(id){return chartModels.find(m=>m[0]===id)?.[1]||id;}
function matrixCell(value,metric,best=false){
 const label=metric==='sr'?(value*100).toFixed(2):value.toFixed(4);
 return `<td><span class="heat-cell ${best?'is-best':''}" style="--heat:${heatColor(value)};--heat-ink:${heatInk(value)}">${label}</span></td>`;
}
function initBenchmarkMatrix(){
 const host=$('#benchmark-matrix');let mode='attributes',metric='sr',reference='best';
 host.innerHTML=`<div class="matrix-heading"><div><p class="eyebrow">ALL EIGHT SYSTEMS</p><h3>The complete benchmark comparison.</h3></div><a href="data/report-main-results.csv" download>Download data ↗</a></div><div class="matrix-tabs" role="tablist" aria-label="Benchmark tables"><button data-matrix="attributes" role="tab" aria-selected="true">Overall & task groups</button><button data-matrix="tasks" role="tab" aria-selected="false" tabindex="-1">All 26 tasks</button><button data-matrix="shifts" role="tab" aria-selected="false" tabindex="-1">Distribution shifts</button><button data-matrix="field" role="tab" aria-selected="false" tabindex="-1">GPT-6-Astra vs. field</button></div><div class="matrix-metric" aria-label="Table metric"><button data-matrix-metric="sr" aria-pressed="true">Success rate (%)</button><button data-matrix-metric="score" aria-pressed="false">Score</button></div><div id="matrix-content" role="tabpanel"></div>`;
 function draw(){
  const target=$('#matrix-content');host.querySelector('.matrix-metric').hidden=mode==='tasks';
  if(mode==='tasks'){target.innerHTML=taskResultsMarkup();initTaskTable();return;}
  if(mode==='field'){drawField(target);return;}
  const shifts=mode==='shifts',groups=shifts?['object','background','instruction','mix']:['Low','Medium','High','Mobile','Fixed','Short Horizon','Long Horizon'],labels=shifts?['Object','Background','Instruction','Mixed']:['Low','Medium','High','Mobile','Tabletop','Short','Long'];
  const systems=[...reportFigures.models].sort((a,b)=>b.sr-a.sr),max=(get)=>Math.max(...systems.map(get));
  target.innerHTML=`<div class="table-scroll benchmark-scroll" tabindex="0" role="region" aria-label="Eight-system comparison"><table class="benchmark-table"><thead><tr><th rowspan="2" scope="col">System</th>${shifts?'<th colspan="4" scope="colgroup">Controlled perturbations</th>':'<th colspan="2" scope="colgroup">Overall</th><th colspan="3" scope="colgroup">Precision</th><th colspan="2" scope="colgroup">Mobility</th><th colspan="2" scope="colgroup">Horizon</th>'}</tr><tr>${shifts?'':'<th>SR (%)</th><th>Score</th>'}${labels.map(l=>`<th scope="col">${l}</th>`).join('')}</tr></thead><tbody>${systems.map(m=>`<tr class="${m.id==='Astra (ICL)'?'astra-row':''}"><th scope="row">${modelLabel(m.id)}<small>${m.id==='Astra (ICL)'?'single-shot ICL':''}</small></th>${shifts?'':matrixCell(m.sr,'sr',m.sr===max(x=>x.sr))+matrixCell(m.score,'score',m.score===max(x=>x.score))}${groups.map(g=>{const v=(shifts?m.generalization[g]:m.groups[g])[metric];return matrixCell(v,metric,v===max(x=>(shifts?x.generalization[g]:x.groups[g])[metric]));}).join('')}</tr>`).join('')}</tbody></table></div><div class="heat-legend"><span>${metric==='sr'?'Success rate (%)':'Score'}</span><span>0</span><i></i><span>${metric==='sr'?'100':'1'}</span></div><p class="fineprint">${shifts?'Object: 24 tasks / 120 episodes. Background, instruction, and mixed: 26 tasks / 130 episodes each.':'Task-macro means · 26 tasks / 510 episodes per system. Precision: 14 / 8 / 4 tasks; mobility: 19 / 7; horizon: 19 / 7.'} Bold marks the best value in each column. All cells share an absolute color scale.</p>`;
 }
 function drawField(target){
  target.innerHTML=`<div class="field-controls"><span>Reference</span><div class="seg" role="group" aria-label="Reference system"><button data-ref="best" aria-pressed="${reference==='best'}">Best other system</button><button data-ref="median" aria-pressed="${reference==='median'}">Median of others</button></div><span>Bars show GPT-6-Astra minus the reference on each task. Select a bar to open that task’s episode.</span></div><div class="field-summary" aria-live="polite"></div><div class="viz-figure field-chart" data-viz-linked></div><p class="fineprint">Task-level means from the same 26-task table (${metric==='sr'?'success rate, percentage points':'Score'}). Differences of a few points are within the noise of 20 episodes per task.</p>`;
  const chart=target.querySelector('.field-chart'),draw=()=>{const rows=viz.astraVersusField(chart,{tasks,metric,reference});const pos=rows.filter(r=>r.delta>1e-9).length,neg=rows.filter(r=>r.delta<-1e-9).length,tie=rows.length-pos-neg;target.querySelector('.field-summary').innerHTML=`<div class="pos"><b>${pos}</b><span>tasks where GPT-6-Astra leads the ${reference==='best'?'best other system':'median of the others'}</span></div><div><b>${tie}</b><span>tasks tied</span></div><div class="neg"><b>${neg}</b><span>tasks where it trails</span></div>`;chart.querySelectorAll('.viz-diverge').forEach(g=>g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();g.dispatchEvent(new MouseEvent('click',{bubbles:true}));}}));};
  draw();viz.bindTips(target);viz.resizeRedraw(chart,draw);
 }
 host.addEventListener('click',e=>{const tab=e.target.closest('[data-matrix]'),button=e.target.closest('[data-matrix-metric]'),ref=e.target.closest('[data-ref]');if(ref){reference=ref.dataset.ref;draw();return;}if(tab){mode=tab.dataset.matrix;host.querySelectorAll('[data-matrix]').forEach(b=>{b.setAttribute('aria-selected',String(b===tab));b.tabIndex=b===tab?0:-1;});}else if(button){metric=button.dataset.matrixMetric;host.querySelectorAll('[data-matrix-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}else return;draw();});
 tabKeyboard(host.querySelector('.matrix-tabs'),'[data-matrix]');draw();
}
function tabKeyboard(root,selector){root.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...root.querySelectorAll(selector)],i=buttons.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:buttons.length-1))%buttons.length;buttons[next].click();buttons[next].focus();});}
function renderPoc(){
 const entries=[['astra-poc','GPT-6-Astra','Zero-shot agent'],['pi05-poc','π₀.₅','Retrained on constituent skills'],['openwam-poc-1','OpenWAM · recording 1','Retrained on constituent skills'],['openwam-poc-2','OpenWAM · recording 2','Retrained on constituent skills']];
 $('#case-content').innerHTML=`<div class="case-heading"><h3>Known skills. An unseen composition.</h3><span class="setting-label">SEPARATE EXPERIMENT · ZERO-SHOT</span></div><p class="case-description">This independent POC evaluates a new combination of tasks <strong>outside the 26-task EBench cohort</strong>. The comparison policies are retrained and evaluated on the constituent atomic skills: the objects and skills are familiar, but <strong>the composed evaluation tasks are unseen</strong>. <strong>No ground-truth (GT) trajectories are available for these composed POC tasks</strong>, so evaluation uses <strong>zero-shot execution rather than ICL</strong>, with no demonstration supplied at test time.</p><div class="poc-protocol"><div><span>Training</span><strong>Constituent atomic skills</strong></div><div><span>Evaluation</span><strong>Unseen task combinations</strong></div><div><span>GPT-6-Astra execution</span><strong>Zero-shot · no ICL</strong></div></div><div class="poc-controls"><div class="focus-switch" aria-label="POC model view"><button data-poc-focus="all" aria-pressed="true">Compare all</button>${entries.map(([_,name],i)=>`<button data-poc-focus="${i}" aria-pressed="false">${name}</button>`).join('')}</div><button class="poc-play">Play all ▷</button></div><div class="poc-videos">${entries.map(([file,name,condition])=>video(`media/poc/${file}.mp4`,name,condition,'Compositional evaluation')).join('')}</div><p class="fineprint">Four supplied recordings. POC results are separate from the main benchmark and have no reported aggregate success rate here. The two OpenWAM recordings retain their supplied numbering; checkpoint labels remain unconfirmed.</p>`;
 const area=$('#case-content');area.querySelectorAll('[data-poc-focus]').forEach(b=>b.addEventListener('click',()=>{const focus=b.dataset.pocFocus;area.querySelector('.poc-videos').dataset.focus=focus;area.querySelectorAll('[data-poc-focus]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));area.querySelectorAll('.evidence-video').forEach((f,i)=>{f.hidden=focus!=='all'&&+focus!==i;if(f.hidden)f.querySelector('video').pause();});}));
 area.querySelector('.poc-play').addEventListener('click',async()=>{const visible=[...area.querySelectorAll('.evidence-video:not([hidden]) video')],play=visible.every(v=>v.paused);for(const v of visible){if(play){if(!v.src)v.src=v.dataset.src;v.muted=true;try{await v.play();}catch{v.controls=true;}}else v.pause();}});
 for(const event of ['play','pause','ended'])area.querySelector('.poc-videos').addEventListener(event,()=>{area.querySelector('.poc-play').textContent=[...area.querySelectorAll('video')].some(v=>!v.paused&&!v.ended)?'Pause all Ⅱ':'Play all ▷';},true);
 initVideos();
}
function initBehavior(){
 const entries={apple:{heading:'A failed transport changes the next attempt.',input:'',action:'',body:'',task:'apple_to_fruit_bowl',seed:'006',score:1},coffee:{heading:'Adapting contact after an unsuccessful attempt.',input:'“Measured local EEF z is not height above the tabletop.”',action:'“Angle spoon edge down to tabletop behind beans”',body:'The supplied prompt warns about contact height. GPT-6-Astra’s recorded action description then accompanies changes in spoon height and tilt. The rollout ends with partial credit; it does not establish successful contact or complete bean collection.',task:'collect_coffee_beans',seed:'013',score:.5},fruit:{heading:'Reconciling the instruction with the example.',input:'“Make a fruit milkshake directly in the cup.”',action:'“Carry the secured fruit above the small cup, not the large jug.”',body:'The historical example uses a jug, while the live instruction specifies a cup. The demonstration explicitly defers the destination to the live instruction. GPT-6-Astra’s recorded action reflects this distinction, but the complete milkshake task remains unfinished.',task:'fruit',seed:'015',score:.6}};
 function draw(key){const d=entries[key];$('#behavior-content').innerHTML=`<div class="behavior-evidence"><div><h3>${d.heading}</h3><dl class="trace-excerpt"><dt>${key==='coffee'?'Supplied execution guidance':'Live task instruction'}</dt><dd>${d.input}</dd><dt>Recorded action description</dt><dd>${d.action}</dd></dl><p>${d.body}</p><button class="appendix-link" data-appendix="behavior">Read the report annotations ↗</button></div>${video(`media/cases/${d.task}_${d.seed}-web.mp4`,title(d.task),`Episode ${d.seed} · ${key==='apple'?'Success':'Incomplete'} · Terminal Score ${d.score.toFixed(2)}`,'GPT-6-Astra · main cohort')}</div>`;updateBehaviorNarrative(key);initVideos();}
 document.querySelectorAll('[data-behavior]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#behavior-content video').forEach(v=>{v.pause();observer.unobserve(v);});document.querySelectorAll('[data-behavior]').forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1;});draw(b.dataset.behavior);}));tabKeyboard($('.behavior-tabs'),'[data-behavior]');draw('apple');
}
function initDemoLibrary(){
 $('#demo-group').innerHTML=taskGroupOptions();
 let page=0;const size=6,unique=tasks.map(t=>({task:t,demo:demos.find(d=>d.task===t.task)}));
 function draw(){
  const query=$('#demo-search').value.trim().toLowerCase(),group=$('#demo-group').value,outcome=$('#demo-outcome').value;
  const filtered=unique.filter(({task:t,demo:d})=>d&&title(t.task).toLowerCase().includes(query)&&matchesTaskGroup(t,group)&&(outcome==='all'||(outcome==='success'?d.sr:!d.sr))),pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages-1);
  $('#library-grid').querySelectorAll('video').forEach(v=>{v.pause();observer.unobserve(v);});
  $('#library-grid').innerHTML=filtered.slice(page*size,page*size+size).map(({task:t,demo:d})=>`<article class="library-item">${video(d.path,title(t.task),`<span>Selected episode ${d.seed}: <b>${d.sr?'success':'incomplete'}</b> · Score ${d.score.toFixed(2)}</span><span>Task SR <b>${pct(t['Astra (ICL)_sr'])}%</b> across ${t.episodes} episodes</span>`,`${t.mobility==='Mobile'?'Mobile':'Tabletop'} · ${t.precision.toLowerCase()} precision`)}</article>`).join('')||'<p>No tasks match these filters.</p>';
  $('#library-count').textContent=`${filtered.length} tasks · ${filtered.length? page*size+1:0}–${Math.min((page+1)*size,filtered.length)} shown`;
  $('#demo-page').textContent=`${page+1} / ${pages}`;$('#demo-prev').disabled=page===0;$('#demo-next').disabled=page===pages-1;initVideos();
 }
 for(const id of ['#demo-search','#demo-group','#demo-outcome'])$(id).addEventListener(id==='#demo-search'?'input':'change',()=>{page=0;draw();});$('#demo-prev').addEventListener('click',()=>{page--;draw();});$('#demo-next').addEventListener('click',()=>{page++;draw();});draw();
}
async function initEpisodeOutcomes(){
 const response=await fetch('data/episodes.json');if(!response.ok)throw Error('Episode outcomes unavailable');const episodes=await response.json(),groups=[{id:'success',name:'Complete success',color:'#3456ef',test:d=>d.sr===1},{id:'partial',name:'Incomplete · positive score',color:'#a9b8f8',test:d=>d.sr===0&&d.score>0},{id:'zero',name:'Incomplete · zero score',color:'#dde3ee',test:d=>d.sr===0&&d.score===0}];
 const host=$('#episode-outcomes');let order='success',group='all',filter=null;
 host.innerHTML=`<div class="outcome-heading"><h3>Most incomplete episodes still make measurable progress.</h3><p>510 retained episodes · one square per episode · server-terminal outcomes · one row per task</p></div><div class="outcome-legend-row" role="group" aria-label="Episode outcome classes">${groups.map(g=>{const n=episodes.filter(g.test).length;return `<button data-outcome-filter="${g.id}" aria-pressed="false" style="--outcome:${g.color}"><i aria-hidden="true"></i><strong>${n}</strong><span>${g.name}</span><small>${(n/episodes.length*100).toFixed(1)}%</small></button>`;}).join('')}</div><div class="outcome-toolbar"><label>Sort rows<select data-outcome-sort aria-label="Sort rows"><option value="success">Most successes first</option><option value="zero">Most zero-score episodes first</option><option value="task">Task name</option></select></label><label>Task attribute<select data-outcome-group aria-label="Task attribute">${taskGroupOptions()}</select></label></div><div class="outcome-rows" data-viz-rows role="list"></div><p class="outcome-readout fineprint" aria-live="polite">Hover a square to see its episode. Select a task name to watch its selected episode.</p><p class="fineprint">Episode-weighted success is 46.47%; the headline 46.73% is the equal-weight mean across tasks. Partial Score follows each task’s scoring rules.</p>`;
 const rowsHost=host.querySelector('[data-viz-rows]');
 function draw(){const rows=viz.outcomeRows(rowsHost,{episodes,tasks,order,group,filter});const shown=rows.reduce((s,r)=>s+r.list.length,0);host.querySelector('.outcome-readout').textContent=filter?`${groups.find(g=>g.id===filter).name}: ${rows.reduce((s,r)=>s+r.counts[filter],0)} of ${shown} shown episodes highlighted.`:`${rows.length} tasks · ${shown} episodes shown. Hover a square to see its episode; select a task name to watch its selected episode.`;}
 host.querySelector('[data-outcome-sort]').addEventListener('change',e=>{order=e.target.value;draw();});
 host.querySelector('[data-outcome-group]').addEventListener('change',e=>{group=e.target.value;draw();});
 host.addEventListener('click',e=>{const button=e.target.closest('[data-outcome-filter]');if(!button)return;const key=button.dataset.outcomeFilter;filter=filter===key?null:key;host.querySelectorAll('[data-outcome-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.outcomeFilter===filter)));draw();});
 host.addEventListener('pointerover',e=>{const c=e.target.closest('.cell');if(c)host.querySelector('.outcome-readout').textContent=c.dataset.tip.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();});
 viz.bindTips(host);draw();
}
let timingPromise;
function initTimingCharts(root=document){
 const hosts=[...root.querySelectorAll('[data-timing]:not([data-timing-ready])')];if(!hosts.length)return;
 timingPromise=timingPromise||fetch('data/execution-timing.json').then(r=>{if(!r.ok)throw Error('timing');return r.json();});
 timingPromise.then(data=>{hosts.forEach(host=>{host.dataset.timingReady='true';const draw=()=>viz.timingBars(host,{episodes:data.episodes});draw();viz.bindTips(host);viz.resizeRedraw(host,draw);});}).catch(()=>hosts.forEach(h=>h.innerHTML='<p class="fineprint">Timing data could not load.</p>'));
}
function initSafetyEvidence(){
 const cases={
  contact:{title:'Contact height remains uncertain.',path:'collect_coffee_beans_013-web.mp4',label:'Coffee-bean collection · episode 013',result:'Incomplete · terminal Score 0.50',observation:'The recorded action descriptions progress from angling the spoon toward the table to sweeping with the fingers, then lowering and tilting the scraping surface. The episode remains incomplete.',risk:'A requested correction does not establish that the intended contact was achieved. Repeating a sweep with an uncertain surface height could miss the beans or drive a tool into the table.',question:'Can the controller verify contact and bound force before continuing the sweep?',source:'Main-cohort recording; public action descriptions at calls 21 and 45–47. The supplied guidance already distinguishes local EEF height from tabletop height.'},
  clearance:{title:'An obstructed closure calls for a new plan.',path:'astra-glasses.mp4',label:'Glasses packing · selected GPT-6-Astra rollout',result:'Temples protrude · closure unfinished',observation:'After the initial transfer, the glasses remain partly unfolded with their temples protruding from the case. Further adjustments leave lid closure unresolved.',risk:'On hardware, pursuing closure without first resolving the obstruction could pinch or damage the glasses. This is a risk implied by the geometry, not observed breakage in this recording.',question:'Can the controller detect the obstruction and refold the glasses before attempting closure?',source:'Report glasses-packing comparison. The selected OpenWAM rollout folds the temples and closes the case; the corresponding three-model comparison is available below.'},
  grasp:{title:'A recovered slip still matters for safety.',path:'apple_to_fruit_bowl_006-web.mp4',label:'Apple to fruit bowl · episode 006',result:'Success · terminal Score 1.00',observation:'After a failed transport, GPT-6-Astra inspects the scene, regrasps the apple, and changes to an arm-only transport attempt. Its action note explicitly refers to the earlier base-motion slip.',risk:'The final success label hides an intermediate loss of the held object. A similar event involving a fragile object or a person nearby could be unacceptable even if the task were eventually completed.',question:'Can grasp monitoring interrupt transport before the object is lost, rather than relying on recovery afterward?',source:'Main-cohort recording and public action notes at calls 10, 11, and 17. The agent’s explanation does not independently establish the physical cause of the slip.'}
 };
 const tabs=$('.safety-tabs'),panel=$('#safety-content');
 function draw(key){
  panel.querySelectorAll('video').forEach(v=>{v.pause();observer.unobserve(v);});
  const item=cases[key];
  panel.setAttribute('aria-labelledby','safety-tab-'+key);
  panel.innerHTML=`<div class="safety-evidence"><div class="safety-case-copy"><h3>${item.title}</h3><dl><dt>Observed in the rollout</dt><dd>${item.observation}</dd><dt>Real-world safety question</dt><dd>${item.risk}</dd></dl><p class="safety-question"><strong>${item.question}</strong></p></div>${video('media/cases/'+item.path,item.label,item.result,'GPT-6-Astra · safety case')}</div><p class="fineprint safety-source">${item.source}</p>`;
  tabs.querySelectorAll('[data-safety]').forEach(b=>{const selected=b.dataset.safety===key;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});
  initVideos();
 }
 tabs.addEventListener('click',e=>{const button=e.target.closest('[data-safety]');if(button)draw(button.dataset.safety);});
 tabKeyboard(tabs,'[data-safety]');draw('contact');
}
function initResearch(){initBenchmarkMatrix();initBehavior();initSafetyEvidence();initDemoLibrary();initTimingCharts();initEpisodeOutcomes().catch(()=>{$('#episode-outcomes').innerHTML='<p>Episode data could not load. Please reload.</p>';});}
